  `email_sent_at` datetime DEFAULT NULL COMMENT 'Timestamp when email was sent',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `closed_by` (`closed_by`),
  KEY `idx_email_sent` (`email_sent`),
  CONSTRAINT `daily_report_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
